 function setDraftAddress(id){const url=new URL(w.location.href);if(id)url.searchParams.set('draft',id);else url.searchParams.delete('draft');w.history.replaceState(null,'',url);}
 function snapshot(){try{return dirty()?recoveryRecord(input(),{ownerId:publicId,story:current,genres:catalog.genres}):null;}catch{return {text_only:true,format:'fas-studio-recovery-v1',owner:publicId,saved_at:new Date().toISOString(),source_id:current?.id??null,base_version:current?.updated_at??null,values:{...blank(),title:field('title').value,summary:field('summary').value,body:editor.innerText,body_document:null}};}}
 function checkpoint(){if(disposed||fileItem||view!=='edit')return;const record=snapshot();if(!record){recovery.clear();$('[data-recovery-status]').textContent='';return;}let valid=true;try{parseRecovery(JSON.stringify(record),{ownerId:publicId,genres:catalog.genres});}catch{valid=false;}const saved=valid&&recovery.write(record);const label=$('[data-recovery-status]'),message=saved?'Unsaved changes protected in this tab.':'Automatic recovery is unavailable. Keep this page open; download your writing under More options.';if(label.textContent!==message)label.textContent=message;label.dataset.error=String(!saved);}
 function renderRecovery(){if(!pendingRecovery)return;$('[data-recovery-description]').textContent='Writing from '+new Date(pendingRecovery.saved_at).toLocaleString()+'. Recovering does not publish or overwrite newer saved work.'+(pendingRecovery.text_only?' This is a text-only copy; review formatting and details.':'');$('[data-resume-recovery]').hidden=!pendingRecovery.source_id||!!pendingRecovery.text_only;$('[data-recovery-notice]').hidden=view!=='library';}
 function restoreCopy(record){try{validateStory({...record.values,title:record.values.title?.trim()?record.values.title:'Untitled recovery'},catalog.genres);}catch{$('[data-recovery-feedback]').textContent='This copy exceeds editor limits. Download its text to keep every word before editing a shorter version.';return;}const values={...record.values,cover_asset_id:null,scheduled_at:null,publishing_identity:catalog.publishing?.can_publish_as_fas?record.values.publishing_identity:'personal'};fill();const empty=savedSignature;fill(values);savedSignature=empty;pendingRecovery=null;recoveredPause=true;showView('edit');changed();field('title').focus();}
