 $('[data-resume-recovery]').addEventListener('click',async()=>{if(busy||!pendingRecovery)return;busy=true;const record=pendingRecovery;$('[data-resume-recovery]').disabled=true;try{validateStory({...record.values,title:record.values.title?.trim()?record.values.title:'Untitled recovery'},catalog.genres);const r=await service.read(record.source_id);if(disposed)return;if(!canResumeRecovery(record,r.story)){$('[data-recovery-feedback]').textContent='The saved version changed or is no longer an unscheduled draft. Recover as a new draft to keep both versions.';return;}fill(r.story,r.assets);const baseline=savedSignature;fill({...r.story,...record.values},r.assets);savedSignature=baseline;pendingRecovery=null;recoveredPause=true;showView('edit');changed();field('title').focus();}catch(e){if(e instanceof StudioAccessError)error(e);else if(!disposed)$('[data-recovery-feedback]').textContent=e.message;}finally{busy=false;if(!disposed){$('[data-resume-recovery]').disabled=false;update();}}});

 const dispose=()=>{seriesEditor.dispose();fileSeriesEditor.dispose();publishReview.dispose();storyHistory.dispose();fileHistory.dispose();filePackageEditor?.dispose();packageEditor.dispose();previewPlayer?.();disposed=true;clearTimeout(timer);clearInterval(accessTimer);releaseCover();if(cropObjectURL)URL.revokeObjectURL(cropObjectURL);if(dialog.open)dialog.close();if(newDialog.open)newDialog.close();if(templatesDialog.open)templatesDialog.close();if(deleteDialog.open)deleteDialog.close();d.removeEventListener('selectionchange',trackRange);d.removeEventListener('visibilitychange',recheck);w.removeEventListener('beforeunload',unload);root.replaceChildren();};dispose.recovery=()=>snapshot()??pendingRecovery;dispose.forgetRecovery=()=>{pendingRecovery=null;recovery.clear();};dispose.canLeave=()=>{if(busy){tell('Wait for the current operation before signing out.');return false;}return mayLeave();};return dispose;
